  const state={products:[],categories:[],banners:[],promos:[],portfolio:[],testimonials:[],reviewInbox:[],faqs:[],announcements:[],settings:{...DEFAULT_SETTINGS},activeTab:'dashboard',theme:localStorage.getItem('simbaa-theme')||'dark',lang:localStorage.getItem('simbaa-language')||'id'};
