  function renderPromos(){$('promotionsList').innerHTML=state.promos.map(p=>{const now=Date.now(),start=p.starts_at?new Date(p.starts_at).getTime():0,end=p.ends_at?new Date(p.ends_at).getTime():Infinity;const stateLabel=!p.is_active?'Draft / nonaktif':now<start?'Terjadwal':now>end?'Kedaluwarsa':'Aktif';return `<article class="admin-list-row promo-admin-card"><div><b>${esc(p.name)}</b><small>${esc(p.code||'Tanpa kode')} · ${p.promo_type==='percent'?`${p.discount_value}%`:money(p.discount_value)} · Minimum ${money(p.minimum_order)}</small><small><span class="pill">${stateLabel}</span> ${p.product_id?'Promo produk tertentu':'Promo umum'}</small><p>${esc(p.terms||'Belum ada syarat tambahan.')}</p><small>${p.starts_at?new Date(p.starts_at).toLocaleString('id-ID'):'Mulai langsung'} — ${p.ends_at?new Date(p.ends_at).toLocaleString('id-ID'):'Tanpa batas akhir'}</small></div><div class="admin-row-actions"><button type="button" data-edit-promo="${esc(p.id)}">✏️ Edit</button><button type="button" data-toggle-promo="${esc(p.id)}">${p.is_active?'⏸ Nonaktifkan':'▶ Aktifkan'}</button><button type="button" class="danger-action" data-delete-promo="${esc(p.id)}">🗑 Hapus</button></div></article>`;}).join('')||'<p>Belum ada promo. Tambahkan hanya penawaran yang benar-benar berlaku.</p>';}

  async function savePromo(e){e.preventDefault();setStatus('promoStatus','Menyimpan…');try{const id=value('promoId'),name=value('promoName'),code=value('promoCode')||null;const start=value('promoStart'),end=value('promoEnd');const payload={name,code,product_id:value('promoProduct')||null,promo_type:value('promoType'),discount_value:value('promoType')==='fixed'?parseRupiah(value('promoValue')):Number(value('promoValue')||0),minimum_order:parseRupiah(value('promoMinimum')),sort_order:Number(value('promoOrder')||0),starts_at:start?new Date(start).toISOString():null,ends_at:end?new Date(end).toISOString():null,terms:value('promoTerms'),is_active:checked('promoActive'),updated_at:new Date().toISOString()};if(!name)throw new Error('Nama promo wajib diisi.');if(!Number.isFinite(payload.discount_value)||payload.discount_value<=0||!Number.isFinite(payload.minimum_order)||payload.minimum_order<0)throw new Error('Nilai diskon harus berupa angka lebih dari 0 dan minimum pembelian tidak boleh negatif.');if(payload.promo_type==='percent'&&payload.discount_value>=100)throw new Error('Diskon persentase harus di bawah 100% agar nilai transaksi tidak menjadi gratis. Periksa modal dan margin sebelum memublikasikan promo.');if(payload.promo_type==='fixed'){const linked=state.products.find(p=>String(p.id)===String(payload.product_id||''));if(linked&&Number(linked.price)>0&&payload.discount_value>=Number(linked.price))throw new Error('Diskon nominal tidak boleh sama dengan atau melebihi harga produk.');if((!linked||Number(linked.price)<=0)&&payload.minimum_order<payload.discount_value)throw new Error('Promo nominal tanpa harga produk yang pasti wajib memiliki minimum pembelian sekurang-kurangnya sebesar diskon agar nilai pesanan tidak habis oleh promo.');}if(payload.ends_at&&payload.starts_at&&new Date(payload.ends_at)<=new Date(payload.starts_at))throw new Error('Waktu berakhir harus setelah waktu mulai.');const r=id?await sb.from('promotions').update(payload).eq('id',id):await sb.from('promotions').insert(payload);if(r.error)throw r.error;await log(id?'update':'create','promotion',id||code||name,`${id?'Mengubah':'Menambah'} promo ${name}`);resetPromo();await refreshAll();notify('Promo disimpan.');}catch(err){setStatus('promoStatus',err.message,true);}}
