  function musicPlaylist(){const rows=Array.isArray(state.settings.music_playlist)?state.settings.music_playlist:[];if(rows.length)return rows;const legacy=String(state.settings.audio_intro_url||'').trim();return legacy?[{id:'legacy',title:state.settings.music_title||'SIMBAA Digital Vibes',url:legacy,source_type:'url',default:true}]:[];}
  function spotifyEmbed(track){if(track?.spotify_embed_url&&/^https:\/\/open\.spotify\.com\/embed\/(track|album|playlist)\/[A-Za-z0-9]+/i.test(track.spotify_embed_url))return track.spotify_embed_url;const type=track?.spotify_type,id=track?.spotify_id;return ['track','album','playlist'].includes(type)&&/^[A-Za-z0-9]+$/.test(id||'')?`https://open.spotify.com/embed/${type}/${id}?utm_source=generator&theme=0`:'';}
  function renderAdminMusicPlaylist(){const host=$('adminMusicPlaylist');if(!host)return;const list=musicPlaylist();const count=$('musicPlaylistCount');if(count)count.textContent=`${list.length} lagu`;host.innerHTML=list.map((track,index)=>{const spotify=track.source_type==='spotify';const cover=track.cover_url||'';return `<article class="admin-music-row"><div class="admin-music-index">${String(index+1).padStart(2,'0')}</div><div class="admin-music-cover">${cover?`<img src="${esc(cover)}" alt="" loading="lazy">`:`<span>${spotify?'♫':'♪'}</span>`}</div><div class="admin-music-info"><b>${esc(track.title||'Tanpa judul')}</b><small>${esc(track.artist|| (spotify?'Spotify Embed':track.source_type==='upload'?'MP3 · Supabase Storage':'Audio URL'))}${track.default?' · Default':''}</small></div><div class="admin-music-actions"><button type="button" data-music-up="${esc(track.id)}" ${index===0?'disabled':''} aria-label="Naikkan urutan">↑</button><button type="button" data-music-down="${esc(track.id)}" ${index===list.length-1?'disabled':''} aria-label="Turunkan urutan">↓</button><button type="button" data-music-preview="${esc(track.id)}">Preview</button><button type="button" data-music-default="${esc(track.id)}" ${track.default?'disabled':''}>${track.default?'Default':'Jadikan default'}</button><button type="button" data-music-rename="${esc(track.id)}">Edit</button><button type="button" class="danger" data-music-delete="${esc(track.id)}">Hapus</button></div></article>`;}).join('')||'<p class="music-admin-empty">Belum ada lagu. Upload MP3 atau tambahkan tautan Spotify.</p>';}
  async function persistMusicPlaylist(next,summary){const def=next.find(x=>x.default);const payload={...state.settings,music_playlist:next,music_default_id:def?.id||'',audio_intro_url:def&&def.source_type!=='spotify'?def.url||null:null,music_title:def?.title||'SIMBAA Digital Vibes',updated_at:new Date().toISOString()};const {error}=await sb.from('store_settings').upsert({key:'main',value:payload,updated_at:new Date().toISOString()},{onConflict:'key'});if(error)throw error;state.settings=payload;await log('update','music_playlist','main',summary);renderAdminMusicPlaylist();notify('Playlist musik tersimpan.');}
  async function uploadMusicTrack(){const input=$('storeMusicFile'),files=Array.from(input?.files||[]);if(!files.length){notify('Pilih satu atau beberapa file audio terlebih dahulu.',true);return;}const allowedExt=/\.(mp3|m4a|aac|wav|ogg|webm)$/i,types=['audio/mpeg','audio/mp3','audio/mp4','audio/aac','audio/wav','audio/x-wav','audio/ogg','audio/webm'];for(const file of files){if(!types.includes(file.type)&&!allowedExt.test(file.name)){notify(`Format ${file.name} tidak didukung. Gunakan MP3, M4A, AAC, WAV, OGG, atau WebM.`,true);return;}if(file.size>20*1024*1024){notify(`Ukuran ${file.name} melebihi 20 MB.`,true);return;}}const button=$('uploadMusicButton'),uploaded=[];if(button){button.disabled=true;button.textContent='Menyiapkan upload…';}try{const list=musicPlaylist().map(x=>({...x}));let hasDefault=list.some(x=>x.default);for(let i=0;i<files.length;i++){const file=files[i];if(button)button.textContent=`Mengunggah ${i+1}/${files.length}…`;const ext=(file.name.split('.').pop()||'mp3').toLowerCase().replace(/[^a-z0-9]/g,'');const path=`playlist/${crypto.randomUUID()}.${ext}`;const {error}=await sb.storage.from('simbaa-audio').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type||({mp3:'audio/mpeg',m4a:'audio/mp4',aac:'audio/aac',wav:'audio/wav',ogg:'audio/ogg',webm:'audio/webm'}[ext]||'application/octet-stream')});if(error)throw error;uploaded.push(path);const url=sb.storage.from('simbaa-audio').getPublicUrl(path).data.publicUrl;list.push({id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,'').slice(0,100),url,storage_path:path,source_type:'upload',default:!hasDefault});hasDefault=true;}await persistMusicPlaylist(list,`Mengunggah ${files.length} lagu MP3`);input.value='';}catch(err){if(uploaded.length)await sb.storage.from('simbaa-audio').remove(uploaded);notify(err.message||'Upload audio gagal.',true);}finally{if(button){button.disabled=false;button.textContent='＋ Upload lagu';}}}
  async function addMusicUrl(){const input=$('storeMusicUrl'),url=value('storeMusicUrl');if(!url)return notify('Masukkan URL audio.',true);let parsed;try{parsed=new URL(url);}catch{return notify('URL audio tidak valid.',true);}if(parsed.protocol!=='https:')return notify('URL audio harus menggunakan HTTPS.',true);if(!/\.(mp3|m4a|aac|wav|ogg|webm)(\?|#|$)/i.test(parsed.pathname+parsed.search+parsed.hash))return notify('URL harus mengarah langsung ke file audio, bukan halaman Spotify.',true);const title=prompt('Nama lagu:',decodeURIComponent(parsed.pathname.split('/').pop().replace(/\.[^.]+$/,'')).slice(0,100)||'SIMBAA Music');if(title===null)return;const list=musicPlaylist().map(x=>({...x}));const hasDefault=list.some(x=>x.default);list.push({id:crypto.randomUUID(),title:title.trim().slice(0,100)||'SIMBAA Music',url:parsed.href,source_type:'url',default:!hasDefault});try{await persistMusicPlaylist(list,`Menambahkan URL audio ${title}`);input.value='';}catch(err){notify(err.message,true);}}
