  let adminMusicPreview=null;async function previewMusicTrack(id){const track=musicPlaylist().find(x=>x.id===id);if(!track)return;const host=$('adminMusicPreviewEmbed');if(adminMusicPreview){adminMusicPreview.pause();adminMusicPreview=null;}if(host){host.hidden=false;if(track.source_type==='spotify'){adminMusicPreview=null;const src=spotifyEmbed(track);host.innerHTML=src?`<iframe title="Preview Spotify ${esc(track.title)}" src="${esc(src)}" width="100%" height="152" frameborder="0" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>`:'<p>Spotify Embed tidak valid.</p>';return;}host.innerHTML='<audio controls preload="metadata"></audio>';const player=host.querySelector('audio');adminMusicPreview=player;player.src=track.url;player.volume=.35;try{await player.play();notify('Preview MP3 diputar.');}catch{notify('Tekan Play pada preview untuk memulai audio.',true);}return;}if(track.source_type==='spotify'){notify('Preview Spotify tersedia di halaman Music Studio.',true);return;}adminMusicPreview=new Audio(track.url);adminMusicPreview.volume=.35;try{await adminMusicPreview.play();notify('Preview musik diputar.');}catch{notify('Preview gagal diputar. Periksa file atau URL audio.',true);}}
