  async function savePlatforms(e){
    e.preventDefault();setStatus('platformStatus','Menyimpan tautan…');
    try{
      const whatsappNumber=value('platformWhatsappNumber').replace(/\D/g,'');
      if(whatsappNumber.length<8||whatsappNumber.length>16)throw new Error('Nomor WhatsApp CS harus 8–16 digit termasuk kode negara.');
      const urls={tiktok_url:value('platformTikTok'),facebook_url:value('platformFacebook'),instagram_url:value('platformInstagram'),youtube_url:value('platformYouTube'),whatsapp_community_group:value('platformCommunityGroup'),whatsapp_channel:value('platformCommunityChannel')};
      for(const [key,url] of Object.entries(urls)){if(!url)continue;let parsed;try{parsed=new URL(url);}catch{throw new Error(`URL ${key.replace('_url','').replaceAll('_',' ')} tidak valid.`);}if(!['https:','http:'].includes(parsed.protocol))throw new Error('Tautan harus menggunakan HTTPS atau HTTP.');}
      const payload={...state.settings,...urls,whatsapp_number:whatsappNumber,updated_at:new Date().toISOString()};
      const {error}=await sb.from('store_settings').upsert({key:'main',value:payload,updated_at:new Date().toISOString()},{onConflict:'key'});if(error)throw error;
      state.settings=payload;await log('update','platforms','main','Memperbarui nomor CS, komunitas, dan platform sosial SIMBAA');renderPlatforms();
      setStatus('platformStatus','Tautan berhasil disimpan. Footer dan pesan WhatsApp akan memakai pengaturan terbaru.');notify('Tautan komunitas dan sosial tersimpan.');
    }catch(err){setStatus('platformStatus',err.message||'Tautan gagal disimpan.',true);}
  }
