  function setConfigBuilder(rows){const host=$('productConfigBuilder');if(!host)return;const safeRows=Array.isArray(rows)?rows.slice(0,8):[];host.innerHTML=safeRows.map((f,i)=>`<details class="config-builder-row" data-config-row="${i}" ${i===0?'open':''}><summary><span>Field ${i+1} · <b data-config-summary>${esc(f.label||'Pertanyaan baru')}</b></span><em>Atur</em></summary><div class="config-builder-grid"><label>Label untuk pembeli<input data-config="label" value="${esc(f.label||'')}" maxlength="80" placeholder="Contoh: Nama domain"></label><label>Label English<input data-config="label_en" value="${esc(f.label_en||'')}" maxlength="80" placeholder="Domain name"></label><label>Jenis input<select data-config="type"><option value="text" ${f.type==='text'?'selected':''}>Teks singkat</option><option value="textarea" ${f.type==='textarea'?'selected':''}>Teks panjang</option><option value="select" ${f.type==='select'?'selected':''}>Pilihan</option><option value="email" ${f.type==='email'?'selected':''}>Email</option><option value="number" ${f.type==='number'?'selected':''}>Angka</option><option value="tel" ${f.type==='tel'?'selected':''}>Nomor</option><option value="url" ${f.type==='url'?'selected':''}>Link</option></select></label><label>Nilai otomatis<input data-config="default_value" value="${esc(f.default_value||f.default||'')}" maxlength="100" placeholder="Opsional"></label><label class="config-required"><input data-config="required" type="checkbox" ${f.required?'checked':''}> Wajib diisi</label><label class="config-options" data-options-wrap ${f.type==='select'?'':'hidden'}>Pilihan, pisahkan koma<input data-config="options" value="${esc((f.options||[]).join(', '))}" placeholder="Pilihan A, Pilihan B"></label><div class="config-row-actions"><button class="btn btn-danger-soft" type="button" data-remove-config="${i}">Hapus field</button></div></div></details>`).join('')||'<p class="config-empty">Belum ada field. Tambahkan pertanyaan yang benar-benar dibutuhkan pelanggan.</p>'; }

  function collectConfigBuilder(){return $$('[data-config-row]').map(row=>{const get=k=>row.querySelector(`[data-config="${k}"]`);const type=get('type').value;return {label:get('label').value.trim(),label_en:get('label_en').value.trim(),type,default_value:get('default_value')?.value.trim()||'',required:get('required').checked,options:type==='select'?get('options').value.split(',').map(x=>x.trim()).filter(Boolean):[]};}).filter(x=>x.label).slice(0,8);}
