    $('categoryForm').addEventListener('submit',saveCategory);$('cancelCategoryButton').addEventListener('click',resetCategory);$('newCategoryButton')?.addEventListener('click',()=>{resetCategory();openEditor('categoryFormWrap');});$('newProductButton').addEventListener('click',()=>{$('productForm').reset();$('productId').value='';$('productEditorTitle').textContent='Tambah produk baru';$('productPriceType').value='consultation';$('productPrice').value='0';if($('productCostPrice'))$('productCostPrice').value='';if($('productTargetMargin'))$('productTargetMargin').value='30';if($('productPriceSuggestion'))$('productPriceSuggestion').textContent='Kalkulator ini hanya untuk sesi admin. Modal tidak disimpan dan tidak dikirim ke pelanggan.';renderCategoryOptions('development');setConfigBuilder(suggestedConfig(value('productCategory')||'development'));$('productActive').checked=true;$('productBest').checked=false;$('productShowHome').checked=false;openEditor('productFormWrap');});$('cancelProductButton').addEventListener('click',resetProduct);$('productForm').addEventListener('submit',saveProduct);$('adminProductSearch')?.addEventListener('input',renderProducts);$('adminProductCategoryFilters')?.addEventListener('click',e=>{const b=e.target.closest('[data-admin-product-category]');if(!b)return;productCategoryFilter=b.dataset.adminProductCategory;renderProductFilters();renderProducts();});$('productPrice')?.addEventListener('blur',e=>{e.target.value=formatRupiahInput(parseRupiah(e.target.value));});$('productCostPrice')?.addEventListener('blur',e=>{e.target.value=e.target.value?formatRupiahInput(parseRupiah(e.target.value)):'';});$('calculateProductPrice')?.addEventListener('click',calculateProductPrice);$('promoValue')?.addEventListener('blur',e=>{if(value('promoType')==='fixed')e.target.value=formatRupiahInput(parseRupiah(e.target.value));});$('newPromoButton')?.addEventListener('click',()=>{resetPromo();openEditor('promoFormWrap');});$('newPortfolioButton')?.addEventLis