    $('saveBannersButton').addEventListener('click',saveBanners);$('newAnnouncementButton')?.addEventListener('click',()=>openAnnouncement());$('announcementForm')?.addEventListener('submit',saveAnnouncement);$('cancelAnnouncementButton')?.addEventListener('click',resetAnnouncement);$('promoForm').addEventListener('submit',savePromo);$('cancelPromoButton').addEventListener('click',resetPromo);$('portfolioForm').addEventListener('submit',savePortfolio);$('cancelPortfolioButton').addEventListener('click',resetPortfolio);$('testimonialForm').addEventListener('submit',saveTestimonial);$('cancelTestimonialButton').addEventListener('click',resetTestimonial);$('storeSettingsForm')?.addEventListener('submit',saveStoreSettings);$('homeSettingsForm')?.addEventListener('submit',saveHomeSettings);$('appearanceSettingsForm')?.addEventListener('submit',saveAppearanceSettings);$('musicStudioForm')?.addEventListener('submit',saveMusicStudioSettings);$('seoSettingsForm')?.addEventListener('submit',saveSeoSettings);$('policySettingsForm')?.addEventListener('submit',savePolicySettings);$('addSpotifyMusicButton')?.addEventListener('click',addSpotifyMusic);$('importStarterMusicButton')?.addEventListener('click',importStarterMusicTracks);$('storeMusicVolume')?.addEventListener('input',e=>{const out=$('storeMusicVolumeOutput');if(out)out.value=`${e.target.value}%`;});$('uploadMusicButton')?.addEventListener('click',uploadMusicTrack);$('addMusicUrlButton')?.addEventListener('click',addMusicUrl);$('adminMusicPlaylist')?.addEventListener('click',e=>{const b=e.target.closest('[data-music-default],[data-music-delete],[data-music-rename],[data-music-preview],[data-music-up],[data-music-down]');if(!b)return;if(b.dataset.musicPreview)previewMusicTrack(b.dataset.musicPreview);if(b.dataset.musicDefault)setDefaultMusic(b.dataset.musicDefault);if(b.dataset.musicDelete)deleteMusicTrack(b.dataset.musicDelete);if(b.dataset.musicRename)renameMusicTrack(b.dataset.musicRename);if(b.dataset.musicUp)moveMusicTrack(b.dataset.musicUp,-1);if(b.dataset.musicDown)moveMusicTrack(b.dataset.musicDown,1);});$('platformsForm')?.addEventListener('submit',savePlatforms);$('whatsappTemplateForm')?.addEventListener('submit',saveWhatsAppTemplate);$('whatsappTemplateType')?.addEventListener('change',renderWhatsAppTemplates);$('whatsappTemplateBody')?.addEventListener('input',renderWhatsAppTemplatePreview);$('resetWhatsAppTemplate')?.addEventListener('click',()=>{const key=value('whatsappTemplateType');if(!WA_TEMPLATE_DEFAULTS[key])return;$('whatsappTemplateBody').value=WA_TEMPLATE_DEFAULTS[key];renderWhatsAppTemplatePreview();setStatus('whatsappTemplateStatus','Template bawaan dipulihkan. Klik Simpan template untuk menerapkan.');});$('faqForm').addEventListener('submit',saveFaq);$('cancelFaqButton').addEventListener('click',resetFaq);$('refreshActivityButton').addEventListener('click',loadActivity);$('refreshReviewInbox')?.addEventListener('click',refreshAll);
    $('adminMenuToggle')?.addEventListener('click',()=>toggleAdminSidebar());$('adminSidebarClose')?.addEventListener('click',()=>toggleAdminSidebar(false));$('adminSidebarBackdrop')?.addEventListener('click',()=>toggleAdminSidebar(false));function isMobileAdminNav(){return window.matchMedia('(max-width: 900px)').matches;}function toggleAdminSidebar(force){const side=$('adminSidebar'),back=$('adminSidebarBackdrop'),btn=$('adminMenuToggle');if(!side)return;const open=typeof force==='boolean'?force:!side.classList.contains('open');side.classList.toggle('open',open);back?.classList.toggle('show',open&&isMobileAdminNav());btn?.setAttribute('aria-expanded',String(open));document.body.classList.toggle('admin-sidebar-open',open&&isMobileAdminNav());}document.addEventListener('click',e=>{const group=e.target.closest('[data-group]');if(group){const name=group.dataset.group,items=tabGroups[name]||['dashboard'];if(expandedGroup===name&&items.length>1){expandedGroup=null;$('adminSubnav').hidden=true;group.setAttribute('aria-expanded','false');return;}const first=items.includes(state.activeTab)?state.activeTab:items[0];switchTab(first,name);return;}const goTab=e.target.closest('[data-go-tab]');if(goTab){switchTab(goTab.dataset.goTab);if(isMobileAdminNav())toggleAdminSidebar(false);return;}if(e.target.closest('[data-dashboard-new-product]')){$('newProductButton')?.click();return;}const tab=e.target.closest('#adminSubnav [data-tab]');if(tab){const currentGroup=document.querySelector('[data-group].active')?.dataset.group;switchTab(tab.dataset.tab,currentGroup);if(isMobileAdminNav())toggleAdminSidebar(false);}});window.addEventListener('resize',()=>{if(!isMobileAdminNav()){const side=$('adminSidebar');side?.classList.remove('open');$('adminSidebarBackdrop')?.classList.remove('show');document.body.classList.remove('admin-sidebar-open');}});$('adminLanguageToggle')?.addEventListener('click',()=>{state.lang=state.lang==='id'?'en':'id';localStorage.setItem('simbaa-language',state.lang);applyAdminPreferences();notify(state.lang==='en'?'Language preference updated.':'Preferensi bahasa diperbarui.');});$('adminThemeToggle')?.addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('simbaa-theme',state.theme);applyAdminPreferences();notify(state.theme==='dark'?'Dark mode aktif.':'Light mode aktif.');});window.addEventListener('storage',e=>{if(e.key==='simbaa-theme'){state.theme=e.newValue||'dark';applyAdminPreferences();}if(e.key==='simbaa-language'){state.lang=e.newValue||'id';applyAdminPreferences();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleAdminSidebar(false);if(document.body.classList.contains('admin-editor-open'))closeAllEditors();}if(e.key==='Tab'&&document.body.classList.contains('admin-editor-open')){const wrap=document.querySelector('.admin-editor-wrap.is-editor-open,.product-editor-wrap.is-editor-open');if(!wrap)return;const nodes=[...wrap.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>el.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});$('clearActivityButton')?.addEventListener('click',clearActivity);wireActions();applyAdminPreferences();
